/* Light gray text override for terms and conditions */
.terms-text {
  color: #999999 !important;
}

/* Cyan color for normal price labels */
.normal-price-label {
  color: #00FFFF !important;
}

/* Animated background for call-to-action section */
.call-to-action-2 {
  position: relative;
  overflow: hidden;
  min-height: 210px;
  background-image: url('images/call-to-action/source4.gif');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.call-to-action-2::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0.6, 0.8);
  z-index: 0;
}
.call-to-action-2 .container {
  position: relative;
  z-index: 1;
}

.call-to-action-2 h2 {
  position: relative;
  z-index: 1;
}

/* Wormhole animated background for call-to-action section */
.call-to-action-wormhole {
  position: relative;
  overflow: hidden;
  min-height: 300px;
  background-image: url('images/call-to-action/wormhole.gif');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.call-to-action-wormhole::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.6);
  z-index: 0;
}

.call-to-action-wormhole .container {
  position: relative;
  z-index: 1;
}

.call-to-action-wormhole h2,
.call-to-action-wormhole p {
  position: relative;
  z-index: 1;
  color: white;
}
